import graphql.annotations.processor.exceptions.GraphQLAnnotationsException;
import graphql.schema.GraphQLDirective;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import java.lang.reflect.Field;
import graphql.annotations.processor.ProcessingElementsContainer;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import graphql.annotations.processor.retrievers.fieldBuilders.DirectivesBuilder;

@RunWith(MockitoJUnitRunner.class)
public class DirectivesBuilderTest {

    @Mock
    private Field field;

    @Test
    public void buildValidDirectivesTest() {
        ProcessingElementsContainer container = new ProcessingElementsContainer();
        DirectivesBuilder builder = new DirectivesBuilder(field, container);

        GraphQLDirective[] directives = builder.build();

        assertNotNull(directives);
    }

    @Test(expected = GraphQLAnnotationsException.class)
    public void buildInvalidDirectivesTest() {
        doThrow(GraphQLAnnotationsException.class).when(field).getAnnotations();

        ProcessingElementsContainer container = new ProcessingElementsContainer();
        DirectivesBuilder builder = new DirectivesBuilder(field, container);

        builder.build();
    }

    @Test
    public void notNullContainerTest() {
        ProcessingElementsContainer container = new ProcessingElementsContainer();
        DirectivesBuilder builder = new DirectivesBuilder(field, container);

        assertNotNull(builder);
    }

    @Test(expected = NullPointerException.class)
    public void nullContainerTest() {
        ProcessingElementsContainer container = null;
        DirectivesBuilder builder = new DirectivesBuilder(field, container);

        builder.build();
    }
}
